input.command:
node --input-type=module - <<'EOF'
import { screenPayment } from './impl.ts';
import assert from 'node:assert/strict';
const attempt = { id: 'p', customerId: 'c', amountCents: 0, cardCountry: 'US', ipCountry: 'US', priorPayments: 0 };
assert.deepEqual(screenPayment(attempt), { action: 'allow', reasons: [] });
assert.equal(screenPayment({ ...attempt, amountCents: 50_000 }).action, 'allow');
assert.equal(screenPayment({ ...attempt, amountCents: 50_001 }).action, 'review');
assert.equal(screenPayment({ ...attempt, amountCents: 50_001, priorPayments: 1 }).action, 'allow');
assert.equal(screenPayment({ ...attempt, amountCents: 50_001, cardCountry: 'CA' }).action, 'block');
console.log('5 decision scenarios passed');
EOF
